tape( 'the function performs the matrix-vector operation `y = α*A*x + β*y` (row-major, lower)', function test( t ) {
	var expected;
	var alpha;
	var data;
	var beta;
	var out;
	var a;
	var x;
	var y;

	data = rl;

	a = new Complex128Array( data.A );
	x = new Complex128Array( data.x );
	y = new Complex128Array( data.y );

	alpha = new Complex128( data.alpha[0], data.alpha[1] );
	beta = new Complex128( data.beta[0], data.beta[1] );

	expected = new Complex128Array( data.y_out );

	out =	zhemv( data.uplo, data.N, alpha, a, data.strideA1, data.strideA2, data.offsetA, x, data.strideX, data.offsetX, beta, y, data.strideY, data.offsetY );
	t.strictEqual( out, y, 'returns expected value' );
	t.strictEqual( isSameComplex128Array( out, expected ), true, 'returns expected value' );

	t.end();
});

